// Coffee mug
mug_height = 100;       // [40:5:200]
mug_radius = 35;        // [20:60]
wall_thickness = 3;     // [1:0.5:8]
handle_outer = 28;      // [15:50]
handle_inner = 18;      // [8:40]
mug_color = "SteelBlue";

module torus(r1, r2) {
  rotate_extrude($fn = 80)
    translate([r1, 0, 0])
    circle(r = (r1 - r2) / 2, $fn = 32);
}

color(mug_color)
difference() {
  union() {
    cylinder(h = mug_height, r = mug_radius, $fn = 64);
    translate([mug_radius - 4, 0, mug_height / 2])
      rotate([90, 0, 0])
      torus(handle_outer, handle_inner);
  }
  translate([0, 0, wall_thickness])
    cylinder(h = mug_height, r = mug_radius - wall_thickness, $fn = 64);
}
